<script setup lang="ts">import{Head,useForm}from'@inertiajs/vue3';import AdminLayout from'../../Layouts/AdminLayout.vue';const props=defineProps<{item?:any}>();const f=useForm({type:props.item?.type||'page',title:props.item?.title||'',slug:props.item?.slug||'',summary:props.item?.summary||'',content:props.item?.content||'',status:props.item?.status||'draft',sort_order:props.item?.sort_order||0,is_featured:!!props.item?.is_featured,published_at:props.item?.published_at?.slice(0,16)||'',meta_title:props.item?.meta_title||'',meta_description:props.item?.meta_description||'',featured_image:null as File|null,_method:props.item?'patch':'post'});const submit=()=>f.post(props.item?`/admin/content/${props.item.id}`:'/admin/content');const slug=()=>{if(!props.item)f.slug=f.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')};</script><template><Head :title="item?'Edit Content':'Create Content'"/><AdminLayout><h1 class="text-3xl font-extrabold">{{item?'Edit':'Create'}} content</h1><form @submit.prevent="submit" class="card mt-8 grid gap-5 md:grid-cols-2"><label class="label">Type<select v-model="f.type" class="field mt-2"><option v-for="x in ['page','service','service_category','solution','industry','project','testimonial','faq','partner']" :value="x">{{x.replace('_',' ')}}</option></select></label><label class="label">Status<select v-model="f.status" class="field mt-2"><option>draft</option><option>published</option><option>archived</option></select></label><label class="label md:col-span-2">Title<input v-model="f.title" @blur="slug" class="field mt-2"><span class="text-red-600">{{f.errors.title}}</span></label><label class="label md:col-span-2">Slug<input v-model="f.slug" class="field mt-2"><span class="text-red-600">{{f.errors.slug}}</span></label><label class="label md:col-span-2">Summary<textarea v-model="f.summary" class="field mt-2" rows="3"></textarea></label><label class="label md:col-span-2">Content<textarea v-model="f.content" class="field mt-2" rows="10"></textarea></label><label class="label">Sort order<input v-model="f.sort_order" type="number" class="field mt-2"></label><label class="label">Publish at<input v-model="f.published_at" type="datetime-local" class="field mt-2"></label><label class="label md:col-span-2">Featured image<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" class="field mt-2" @change="f.featured_image=($event.target as HTMLInputElement).files?.[0]||null"></label><label class="flex gap-2"><input v-model="f.is_featured" type="checkbox">Featured content</label><div class="md:col-span-2"><button class="btn-primary" :disabled="f.processing">Save content</button></div></form></AdminLayout></template>
